CREATE TABLE IF NOT EXISTS site_content (content_key text PRIMARY KEY, content jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS public_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, summary text NOT NULL DEFAULT '', event_date timestamptz, location text NOT NULL DEFAULT 'Online', registration_url text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS knowledge_resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, summary text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Insights', resource_url text NOT NULL DEFAULT '', resource_type text NOT NULL DEFAULT 'article', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS membership_tiers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, title text NOT NULL, subtitle text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO site_content(content_key,content) VALUES ('homepage', '{"heroTitle":"Build the capability to lead what matters.","heroIntro":"A modern professional institute connecting structured learning, applied competence, credible credentials, continuous development and organisational capability.","experienceTitle":"Learning built for meaningful professional progress.","membershipTitle":"A professional identity that grows with you.","corporateTitle":"Turn learning into organisational capability.","corporateIntro":"Develop workforce capability through tailored learning, executive development and practical assessment.","knowledgeTitle":"Resources for work beyond the classroom.","eventsTitle":"Keep the conversation moving.","footerDescription":"Professional learning, credentials and continuous development.","principlesTitle":"Knowledge → Competence → Performance → Impact","principles":[{"title":"Knowledge","description":"Structured learning and current professional knowledge."},{"title":"Competence","description":"Practice, assessment and evidence of capability."},{"title":"Performance","description":"Transfer learning into real work and leadership."},{"title":"Impact","description":"Create measurable value for people and organisations."}],"heroEyebrow":"PROFESSIONAL DEVELOPMENT · CREDENTIALS · MEMBERSHIP","heroPrimaryCta":"Explore programmes","heroSecondaryCta":"Start an application","heroPanelLabel":"IPMI / DIGITAL INSTITUTE"}') ON CONFLICT(content_key) DO NOTHING;
INSERT INTO membership_tiers(slug,title,subtitle,description,status,sort_order) VALUES ('associate','Associate','Build your foundation','For emerging professionals developing core capability.', 'published',1),('professional','Professional','Demonstrate your practice','For experienced practitioners committed to continuous development.','published',2),('fellow','Fellow','Contribute and lead','For senior professionals with sustained leadership and sector contribution.','published',3) ON CONFLICT(slug) DO NOTHING;
